class TestGeneralValidator:
    """Test app.ingestion.general_validator."""

    def _make_chunk(self, text="Hello world", doc="test.pdf",
                    page=1, ctype="prose"):
        return {
            "chunk_id": "test-id",
            "chunk_text": text,
            "document_name": doc,
            "page_number": page,
            "chunk_type": ctype,
            "token_count": len(text.split()),
            "source_hash": "abc123",
            "section_heading": None,
            "image_file_path": None,
            "figure_references": [],
            "error_code": None,
            "sl_no": None,
            "error_description": None,
            "error_remarks": None,
            "document_version": None,
            "system_name": None,
            "subsystem": None,
            "chapter": None,
            "section": None,
        }

    def test_valid_chunks_pass(self):
        """Normal chunks pass validation."""
        from app.ingestion.general_validator import validate_general_chunks

        chunks = [self._make_chunk(), self._make_chunk("Another chunk")]
        warnings, errors = validate_general_chunks(chunks)
        assert errors == []

    def test_empty_chunk_rejected(self):
        """Empty chunk text produces an error."""
        from app.ingestion.general_validator import validate_general_chunks

        chunks = [self._make_chunk(text="")]
        warnings, errors = validate_general_chunks(chunks)
        assert any("EMPTY" in e for e in errors)

    def test_oversized_chunk_flagged(self):
        """Chunk exceeding MAX_CHUNK_TOKENS produces a warning."""
        from app.ingestion.general_validator import validate_general_chunks

        big_text = "word " * 4000
        chunks = [self._make_chunk(text=big_text)]
        warnings, errors = validate_general_chunks(chunks)
        assert any("OVERSIZE" in w for w in warnings)

    def test_missing_document_rejected(self):
        """Chunk with empty document_name produces an error."""
        from app.ingestion.general_validator import validate_general_chunks

        chunks = [self._make_chunk(doc="")]
        warnings, errors = validate_general_chunks(chunks)
        assert any("MISSING_DOC" in e for e in errors)

    def test_missing_page_warned(self):
        """Chunk with None page_number produces a warning."""
        from app.ingestion.general_validator import validate_general_chunks

        c = self._make_chunk()
        c["page_number"] = None
        warnings, errors = validate_general_chunks([c])
        assert any("NO_PAGE" in w for w in warnings)

    def test_invalid_chunk_type_rejected(self):
        """Chunk with bad chunk_type produces an error."""
        from app.ingestion.general_validator import validate_general_chunks

        c = self._make_chunk()
        c["chunk_type"] = "invalid"
        warnings, errors = validate_general_chunks([c])
        assert any("BAD_TYPE" in e for e in errors)

    def test_duplicate_detected(self):
        """Near-duplicate chunks produce a warning."""
        from app.ingestion.general_validator import validate_general_chunks

        text = "This is a test sentence about motorcycle maintenance"
        c1 = self._make_chunk(text=text)
        c2 = self._make_chunk(text=text + " extra")
        c2["chunk_id"] = "test-id-2"
        warnings, errors = validate_general_chunks([c1, c2])
        assert any("DUPLICATE" in w for w in warnings)

    def test_empty_list_rejected(self):
        """Empty chunk list produces a critical error."""
        from app.ingestion.general_validator import validate_general_chunks

        warnings, errors = validate_general_chunks([])
        assert any("CRITICAL" in e for e in errors)


