# 4. End-to-end ingestion test (isolation from fault-code index)
# ---------------------------------------------------------------------------

class TestIngestGeneral:
    """Test app.ingestion.ingest_general end-to-end."""

    def test_end_to_end_creates_general_index(self, tmp_path):
        """
        Run the full pipeline against the fixture PDF and verify:
        - data/index/general/ is created
        - data/index/faiss.index (existing) is NOT touched
        """
        from unittest.mock import MagicMock, patch

        from app.ingestion.ingest_general import run_general_ingestion

        # Patch the output paths to use tmp_path so we don't touch real data
        import app.ingestion.ingest_general as mod

        general_dir = tmp_path / "general"
        orig_faiss = mod.GENERAL_FAISS_PATH
        orig_chunks = mod.GENERAL_CHUNKS_PATH
        orig_index_dir = mod.GENERAL_INDEX_DIR
        try:
            mod.GENERAL_INDEX_DIR = general_dir
            mod.GENERAL_FAISS_PATH = general_dir / "faiss.index"
            mod.GENERAL_CHUNKS_PATH = general_dir / "chunks.jsonl"

            # Mock the embedder (model not available in CI sandbox)
            mock_embedder = MagicMock()
            # Return a 384-dim vector (matching BGE-small-en-v1.5)
            import numpy as np

            def fake_embed(texts):
                return [np.random.RandomState(42).randn(384).tolist()
                        for _ in texts]
            mock_embedder.embed_documents = fake_embed

            with patch(
                "app.ingestion.ingest_general._embed_chunks",
                side_effect=lambda chunks: np.array(
                    fake_embed([c["chunk_text"] for c in chunks]),
                    dtype=np.float32,
                ),
            ):
                success = run_general_ingestion(FIXTURE_PDF)

            assert success is True

            # Verify index files created
            assert mod.GENERAL_FAISS_PATH.exists()
            assert mod.GENERAL_CHUNKS_PATH.exists()

            # Verify chunks are loadable and have correct source
            with open(mod.GENERAL_CHUNKS_PATH) as f:
                chunks = [json.loads(line) for line in f if line.strip()]
            assert len(chunks) > 0
            for c in chunks:
                assert c["document_name"] == FIXTURE_PDF.name
                assert c["source_hash"] == _fixture_hash()
        finally:
            mod.GENERAL_FAISS_PATH = orig_faiss
            mod.GENERAL_CHUNKS_PATH = orig_chunks
            mod.GENERAL_INDEX_DIR = orig_index_dir

    def test_existing_index_untouched(self, tmp_path):
        """
        Explicitly verify that data/index/faiss.index and
        data/index/chunks.jsonl are never modified by general ingestion.
        """
        from unittest.mock import patch

        import numpy as np

        from app.ingestion.ingest_general import run_general_ingestion
        from app.settings import CHUNKS_STORE_PATH, FAISS_INDEX_PATH

        # Record checksums of existing fault-code index files
        def _hash(p: Path) -> str | None:
            if not p.exists():
                return None
            h = hashlib.sha256()
            with open(p, "rb") as f:
                for chunk in iter(lambda: f.read(65536), b""):
                    h.update(chunk)
            return h.hexdigest()

        faiss_before = _hash(FAISS_INDEX_PATH)
        chunks_before = _hash(CHUNKS_STORE_PATH)

        # Patch output to tmp_path
        import app.ingestion.ingest_general as mod

        general_dir = tmp_path / "general"
        orig_faiss = mod.GENERAL_FAISS_PATH
        orig_chunks = mod.GENERAL_CHUNKS_PATH
        orig_index_dir = mod.GENERAL_INDEX_DIR
        try:
            mod.GENERAL_INDEX_DIR = general_dir
            mod.GENERAL_FAISS_PATH = general_dir / "faiss.index"
            mod.GENERAL_CHUNKS_PATH = general_dir / "chunks.jsonl"

            def fake_embed(chunks):
                rng = np.random.RandomState(42)
                return np.array(
                    [rng.randn(384).tolist() for _ in chunks],
                    dtype=np.float32,
                )

            with patch(
                "app.ingestion.ingest_general._embed_chunks",
                side_effect=fake_embed,
            ):
                run_general_ingestion(FIXTURE_PDF)

            # Verify existing index files are byte-identical
            assert _hash(FAISS_INDEX_PATH) == faiss_before
            assert _hash(CHUNKS_STORE_PATH) == chunks_before
        finally:
            mod.GENERAL_FAISS_PATH = orig_faiss
            mod.GENERAL_CHUNKS_PATH = orig_chunks
            mod.GENERAL_INDEX_DIR = orig_index_dir

    def test_existing_test_suite_unaffected(self):
        """Sanity: the existing fault-code tests still pass."""
        # This is validated by the full test run, but we include an explicit
        # check here for documentation purposes.
        from app.ingestion.chunker import load_chunks
        from app.settings import CHUNKS_STORE_PATH

        if CHUNKS_STORE_PATH.exists():
            chunks = load_chunks(CHUNKS_STORE_PATH)
            assert len(chunks) == 28  # existing fault-code corpus


# ---------------------------------------------------------------------------
# 5. Multi-index retriever tests
# ---------------------------------------------------------------------------

class TestMultiIndexRetriever:
    """Test that the retriever searches both fault-code and general indexes."""

    def _make_chunk_dict(self, text, doc, page, code=None):
        """Minimal chunk dict matching the shared schema."""
        return {
            "chunk_id": f"chunk-{doc}-{page}",
            "chunk_text": text,
            "document_name": doc,
            "page_number": page,
            "chunk_type": "prose",
            "token_count": len(text.split()),
            "source_hash": "abc123",
            "section_heading": None,
            "image_file_path": None,
            "figure_references": [],
            "error_code": code,
            "sl_no": None,
            "error_description": None,
            "error_remarks": None,
            "document_version": None,
            "system_name": None,
            "subsystem": None,
            "chapter": None,
            "section": None,
        }

    def test_retriever_loads_general_index(self, tmp_path):
        """Retriever loads the general index when files exist."""
        import numpy as np
        import faiss

        # Create a minimal general index
        gen_dir = tmp_path / "general"
        gen_dir.mkdir()
        dim = 384
        n = 3
        index = faiss.IndexFlatIP(dim)
        rng = np.random.RandomState(99)
        vecs = rng.randn(n, dim).astype(np.float32)
        faiss.normalize_L2(vecs)
        index.add(vecs)
        faiss.write_index(index, str(gen_dir / "faiss.index"))

        chunks = [
            self._make_chunk_dict("Check tire pressure often", "manual.pdf", 10),
            self._make_chunk_dict("Engine oil capacity 2.9L", "manual.pdf", 20),
            self._make_chunk_dict("Chain slack 25-35mm", "manual.pdf", 30),
        ]
        with open(gen_dir / "chunks.jsonl", "w") as f:
            for c in chunks:
                f.write(json.dumps(c) + "\n")

        # Patch the retriever to use tmp_path for general index
        import app.rag.retriever as mod
        orig_dir = mod._GENERAL_INDEX_DIR
        orig_faiss = mod._GENERAL_FAISS_PATH
        orig_chunks = mod._GENERAL_CHUNKS_PATH
        try:
            mod._GENERAL_INDEX_DIR = gen_dir
            mod._GENERAL_FAISS_PATH = gen_dir / "faiss.index"
            mod._GENERAL_CHUNKS_PATH = gen_dir / "chunks.jsonl"

            r = mod.Retriever()
            assert r._general_index is not None
            assert len(r._general_chunks) == 3
        finally:
            mod._GENERAL_INDEX_DIR = orig_dir
            mod._GENERAL_FAISS_PATH = orig_faiss
            mod._GENERAL_CHUNKS_PATH = orig_chunks

    def test_retriever_works_without_general_index(self):
        """Retriever works normally when general index doesn't exist."""
        import app.rag.retriever as mod

        # Ensure general index paths point to nonexistent location
        orig_dir = mod._GENERAL_INDEX_DIR
        orig_faiss = mod._GENERAL_FAISS_PATH
        orig_chunks = mod._GENERAL_CHUNKS_PATH
        try:
            mod._GENERAL_INDEX_DIR = Path("/nonexistent/general")
            mod._GENERAL_FAISS_PATH = Path("/nonexistent/general/faiss.index")
            mod._GENERAL_CHUNKS_PATH = Path("/nonexistent/general/chunks.jsonl")

            r = mod.Retriever()
            assert r._general_index is None
            assert r._general_chunks == []
            # Should still have the fault-code index
            assert r._index.ntotal > 0
        finally:
            mod._GENERAL_INDEX_DIR = orig_dir
            mod._GENERAL_FAISS_PATH = orig_faiss
            mod._GENERAL_CHUNKS_PATH = orig_chunks
